import React, { useState, useEffect } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
} from 'chart.js';
import {
  buildings,
  sensors,
  generateSensorReading,
  getSensorStatus,
  maintenanceTeam,
  maintenanceHistory,
  energyConsumptionData,
  alertTypes
} from '../../data/infraOSData';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

function InfraOS() {
  const [selectedBuilding, setSelectedBuilding] = useState(null);
  const [selectedSensor, setSelectedSensor] = useState(null);
  const [sensorValue, setSensorValue] = useState('');
  const [isMonitoring, setIsMonitoring] = useState(false);
  const [alerts, setAlerts] = useState([]);
  const [autoMode, setAutoMode] = useState(false);
  const [simulationActive, setSimulationActive] = useState(false);

  useEffect(() => {
    if (autoMode && selectedBuilding && selectedSensor) {
      const interval = setInterval(() => {
        const isAbnormal = Math.random() > 0.7;
        const reading = generateSensorReading(selectedSensor, isAbnormal);
        setSensorValue(reading);
        checkAndGenerateAlert(reading, selectedSensor, selectedBuilding);
      }, 3000);

      return () => clearInterval(interval);
    }
  }, [autoMode, selectedBuilding, selectedSensor]);

  const checkAndGenerateAlert = (value, sensor, building) => {
    const status = getSensorStatus(value, sensor);

    if (status.status !== 'Normal') {
      const alertInfo = alertTypes[sensor.type];
      const newAlert = {
        id: Date.now(),
        building: building.name,
        sensor: sensor.type,
        value: value,
        unit: sensor.unit,
        status: status.status,
        priority: status.priority,
        timestamp: new Date().toLocaleString(),
        icon: alertInfo.icon,
        category: alertInfo.category,
        resolved: false
      };

      setAlerts(prev => [newAlert, ...prev.slice(0, 9)]);
    }
  };

  const handleManualSimulation = () => {
    if (!selectedBuilding || !selectedSensor || !sensorValue) {
      alert('Please select building, sensor and enter a value');
      return;
    }

    setIsMonitoring(true);
    setSimulationActive(true);

    setTimeout(() => {
      checkAndGenerateAlert(parseFloat(sensorValue), selectedSensor, selectedBuilding);
      setIsMonitoring(false);
    }, 1500);
  };

  const assignTechnician = (alert) => {
    const availableTech = maintenanceTeam.filter(t => 
      t.available && t.specialization.toLowerCase().includes(alert.category.toLowerCase())
    );

    if (availableTech.length === 0) {
      return maintenanceTeam.find(t => t.available) || maintenanceTeam[0];
    }

    return availableTech[Math.floor(Math.random() * availableTech.length)];
  };

  const resolveAlert = (alertId) => {
    setAlerts(alerts.map(alert => 
      alert.id === alertId ? { ...alert, resolved: true } : alert
    ));
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
        labels: { color: 'white' }
      },
      title: {
        display: true,
        text: 'Energy Consumption Analysis',
        color: 'white'
      }
    },
    scales: {
      y: {
        ticks: { color: 'white' },
        grid: { color: 'rgba(255,255,255,0.1)' }
      },
      x: {
        ticks: { color: 'white' },
        grid: { color: 'rgba(255,255,255,0.1)' }
      }
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Project Header */}
      <div className="bg-gradient-to-r from-purple-600 to-pink-600 rounded-2xl p-8 mb-8 text-white">
        <div className="flex items-center mb-4">
          <span className="text-6xl mr-4">🏢</span>
          <div>
            <h1 className="text-4xl font-bold mb-2">InfraOS</h1>
            <p className="text-xl">AI-Driven Smart Infrastructure Monitoring & Predictive Maintenance Platform</p>
          </div>
        </div>
      </div>

      {/* Problem vs Solution */}
      <div className="grid md:grid-cols-2 gap-6 mb-8">
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">❌ Current System (Manual)</h3>
          <ul className="space-y-3 text-gray-200">
            <li className="flex items-start">
              <span className="mr-2">1.</span>
              <span>Manual inspection of infrastructure at scheduled intervals</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">2.</span>
              <span>Reactive maintenance after equipment failure</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">3.</span>
              <span>No real-time monitoring of critical parameters</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">4.</span>
              <span>Delayed response to anomalies and emergencies</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">5.</span>
              <span>High maintenance costs and downtime</span>
            </li>
          </ul>
        </div>

        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">✅ Proposed System (Automated)</h3>
          <ul className="space-y-3 text-gray-200">
            <li className="flex items-start">
              <span className="mr-2">1.</span>
              <span>24/7 automated monitoring with IoT sensors</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">2.</span>
              <span>AI-powered predictive maintenance alerts</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">3.</span>
              <span>Real-time anomaly detection and notifications</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">4.</span>
              <span>Automated technician assignment and tracking</span>
            </li>
            <li className="flex items-start">
              <span className="mr-2">5.</span>
              <span>Reduced costs and improved infrastructure lifespan</span>
            </li>
          </ul>
        </div>
      </div>

      {/* Simulation Controls */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-8 border border-white/20 mb-8">
        <h2 className="text-3xl font-bold text-white mb-6">🎯 Interactive Simulation</h2>

        <div className="grid md:grid-cols-3 gap-4 mb-6">
          {/* Building Selection */}
          <div>
            <label className="text-white font-semibold mb-2 block">🏢 Select Building</label>
            <select
              className="w-full px-4 py-3 rounded-lg bg-white/20 text-white border border-white/30 focus:border-purple-400 focus:outline-none"
              value={selectedBuilding?.id || ''}
              onChange={(e) => setSelectedBuilding(buildings.find(b => b.id === parseInt(e.target.value)))}
            >
              <option value="" className="bg-gray-800">Choose a building...</option>
              {buildings.map(building => (
                <option key={building.id} value={building.id} className="bg-gray-800">
                  {building.name} ({building.type})
                </option>
              ))}
            </select>
          </div>

          {/* Sensor Selection */}
          <div>
            <label className="text-white font-semibold mb-2 block">📡 Select Sensor Type</label>
            <select
              className="w-full px-4 py-3 rounded-lg bg-white/20 text-white border border-white/30 focus:border-purple-400 focus:outline-none"
              value={selectedSensor?.id || ''}
              onChange={(e) => setSelectedSensor(sensors.find(s => s.id === parseInt(e.target.value)))}
            >
              <option value="" className="bg-gray-800">Choose a sensor...</option>
              {sensors.map(sensor => (
                <option key={sensor.id} value={sensor.id} className="bg-gray-800">
                  {sensor.type} ({sensor.unit})
                </option>
              ))}
            </select>
          </div>

          {/* Value Input */}
          <div>
            <label className="text-white font-semibold mb-2 block">
              📊 Sensor Value {selectedSensor && `(${selectedSensor.unit})`}
            </label>
            <input
              type="number"
              step="0.01"
              className="w-full px-4 py-3 rounded-lg bg-white/20 text-white placeholder-gray-300 border border-white/30 focus:border-purple-400 focus:outline-none"
              placeholder="Enter value..."
              value={sensorValue}
              onChange={(e) => setSensorValue(e.target.value)}
              disabled={autoMode}
            />
          </div>
        </div>

        {/* Sensor Range Info */}
        {selectedSensor && (
          <div className="bg-blue-900/30 rounded-lg p-4 mb-6">
            <h4 className="text-white font-semibold mb-2">📋 Sensor Information:</h4>
            <div className="grid md:grid-cols-2 gap-4 text-gray-200">
              <div>
                <span className="text-green-400 font-semibold">✅ Normal Range:</span>{' '}
                {selectedSensor.normalRange[0]} - {selectedSensor.normalRange[1]} {selectedSensor.unit}
              </div>
              <div>
                <span className="text-red-400 font-semibold">⚠️ Critical Range:</span>{' '}
                {selectedSensor.criticalRange[0]} - {selectedSensor.criticalRange[1]} {selectedSensor.unit}
              </div>
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="flex gap-4 flex-wrap">
          <button
            onClick={handleManualSimulation}
            disabled={isMonitoring || autoMode || !selectedBuilding || !selectedSensor || !sensorValue}
            className="bg-gradient-to-r from-purple-500 to-pink-500 text-white py-3 px-8 rounded-lg font-semibold hover:shadow-lg transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isMonitoring ? '⏳ Monitoring...' : '🔍 Check Reading'}
          </button>

          <button
            onClick={() => {
              setAutoMode(!autoMode);
              if (!autoMode && selectedSensor) {
                setSensorValue(generateSensorReading(selectedSensor, false));
              }
            }}
            disabled={!selectedBuilding || !selectedSensor}
            className={`${
              autoMode
                ? 'bg-red-500 hover:bg-red-600'
                : 'bg-green-500 hover:bg-green-600'
            } text-white py-3 px-8 rounded-lg font-semibold transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed`}
          >
            {autoMode ? '⏸️ Stop Auto Monitoring' : '▶️ Start Auto Monitoring'}
          </button>

          <button
            onClick={() => {
              if (selectedSensor) {
                setSensorValue(generateSensorReading(selectedSensor, true));
              }
            }}
            disabled={autoMode || !selectedSensor}
            className="bg-orange-500 hover:bg-orange-600 text-white py-3 px-6 rounded-lg font-semibold transition-all duration-300 disabled:opacity-50"
          >
            🔥 Generate Abnormal Reading
          </button>

          <button
            onClick={() => {
              setAlerts([]);
              setSimulationActive(false);
              setSensorValue('');
            }}
            className="bg-gray-600 hover:bg-gray-700 text-white py-3 px-6 rounded-lg font-semibold transition-all duration-300"
          >
            🔄 Reset Simulation
          </button>
        </div>

        {autoMode && (
          <div className="mt-4 bg-green-900/20 border border-green-500/50 rounded-lg p-4">
            <p className="text-green-300 flex items-center">
              <span className="mr-2 text-xl">✅</span>
              <span>Auto-monitoring active. System generates new readings every 3 seconds.</span>
            </p>
          </div>
        )}
      </div>

      {/* Active Alerts */}
      {alerts.length > 0 && (
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20 mb-8">
          <h3 className="text-2xl font-bold text-white mb-4">🚨 Active Alerts & Maintenance Tickets</h3>
          <div className="space-y-4">
            {alerts.map(alert => {
              const technician = assignTechnician(alert);
              return (
                <div
                  key={alert.id}
                  className={`border-2 rounded-lg p-6 ${
                    alert.resolved
                      ? 'bg-gray-900/30 border-gray-500/50'
                      : alert.priority === 'High'
                      ? 'bg-red-900/30 border-red-500/50'
                      : 'bg-orange-900/30 border-orange-500/50'
                  }`}
                >
                  <div className="grid md:grid-cols-4 gap-4">
                    <div className="md:col-span-2">
                      <div className="flex items-center mb-2">
                        <span className="text-3xl mr-3">{alert.icon}</span>
                        <div>
                          <h4 className="text-xl font-bold text-white">
                            {alert.sensor} Alert
                            {alert.resolved && <span className="ml-2 text-green-400">✅ Resolved</span>}
                          </h4>
                          <p className="text-gray-300">{alert.building}</p>
                        </div>
                      </div>
                      <div className="space-y-1 text-gray-200">
                        <p>
                          <span className="font-semibold">Reading:</span> {alert.value} {alert.unit}
                        </p>
                        <p>
                          <span className="font-semibold">Status:</span>{' '}
                          <span
                            className={`font-bold ${
                              alert.status === 'Critical' ? 'text-red-400' : 'text-orange-400'
                            }`}
                          >
                            {alert.status}
                          </span>
                        </p>
                        <p>
                          <span className="font-semibold">Timestamp:</span> {alert.timestamp}
                        </p>
                      </div>
                    </div>

                    <div>
                      <h5 className="text-white font-semibold mb-2">👷 Assigned Technician:</h5>
                      <div className="bg-white/10 rounded-lg p-3">
                        <p className="text-white font-semibold">{technician.name}</p>
                        <p className="text-gray-300 text-sm">{technician.specialization}</p>
                        <p className="text-gray-300 text-sm">⭐ Rating: {technician.rating}/5.0</p>
                      </div>
                    </div>

                    <div className="flex flex-col justify-between">
                      <div>
                        <span
                          className={`inline-block px-4 py-2 rounded-full text-sm font-semibold ${
                            alert.priority === 'High'
                              ? 'bg-red-500 text-white'
                              : 'bg-orange-500 text-white'
                          }`}
                        >
                          {alert.priority} Priority
                        </span>
                      </div>
                      {!alert.resolved && (
                        <button
                          onClick={() => resolveAlert(alert.id)}
                          className="bg-green-500 hover:bg-green-600 text-white py-2 px-4 rounded-lg font-semibold transition-all mt-2"
                        >
                          Mark as Resolved
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Analytics Dashboard */}
      <div className="grid md:grid-cols-2 gap-6 mb-8">
        {/* Energy Consumption Chart */}
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">⚡ Energy Consumption Trends</h3>
          <Line data={energyConsumptionData} options={chartOptions} />
          <p className="text-gray-300 mt-4 text-sm">
            💡 AI Prediction: Energy consumption expected to decrease by 8% next week
          </p>
        </div>

        {/* Maintenance History */}
        <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
          <h3 className="text-2xl font-bold text-white mb-4">📋 Recent Maintenance History</h3>
          <div className="space-y-3 max-h-96 overflow-y-auto">
            {maintenanceHistory.map(record => (
              <div key={record.id} className="bg-white/10 rounded-lg p-4">
                <div className="flex justify-between items-start mb-2">
                  <h4 className="text-white font-semibold">{record.issue}</h4>
                  <span
                    className={`px-3 py-1 rounded-full text-xs font-semibold ${
                      record.status === 'Completed'
                        ? 'bg-green-500 text-white'
                        : 'bg-yellow-500 text-white'
                    }`}
                  >
                    {record.status}
                  </span>
                </div>
                <p className="text-gray-300 text-sm mb-1">{record.building}</p>
                <p className="text-gray-400 text-sm mb-2">
                  {record.date} • {record.technician}
                </p>
                <p className="text-gray-300 text-sm">{record.resolution}</p>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Performance Metrics */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20 mb-8">
        <h3 className="text-2xl font-bold text-white mb-6">📊 System Performance Metrics</h3>
        <div className="grid md:grid-cols-4 gap-4">
          <div className="bg-gradient-to-br from-blue-600/30 to-blue-800/30 rounded-lg p-6 text-center">
            <div className="text-4xl font-bold text-blue-400">{buildings.length}</div>
            <div className="text-gray-300 mt-2">Buildings Monitored</div>
          </div>
          <div className="bg-gradient-to-br from-green-600/30 to-green-800/30 rounded-lg p-6 text-center">
            <div className="text-4xl font-bold text-green-400">{sensors.length * buildings.length}</div>
            <div className="text-gray-300 mt-2">Active Sensors</div>
          </div>
          <div className="bg-gradient-to-br from-purple-600/30 to-purple-800/30 rounded-lg p-6 text-center">
            <div className="text-4xl font-bold text-purple-400">
              {alerts.filter(a => !a.resolved).length}
            </div>
            <div className="text-gray-300 mt-2">Active Alerts</div>
          </div>
          <div className="bg-gradient-to-br from-orange-600/30 to-orange-800/30 rounded-lg p-6 text-center">
            <div className="text-4xl font-bold text-orange-400">98.5%</div>
            <div className="text-gray-300 mt-2">System Uptime</div>
          </div>
        </div>
      </div>

      {/* Expected Outcomes */}
      <div className="bg-white/10 backdrop-blur-lg rounded-xl p-6 border border-white/20">
        <h3 className="text-2xl font-bold text-white mb-4">✨ Expected Outcomes & Benefits</h3>
        <div className="grid md:grid-cols-3 gap-4">
          <div className="bg-green-900/20 rounded-lg p-4">
            <div className="text-3xl mb-2">💰</div>
            <h4 className="font-bold text-white mb-2">Cost Reduction</h4>
            <p className="text-gray-300 text-sm">
              40% reduction in maintenance costs through predictive maintenance
            </p>
          </div>
          <div className="bg-blue-900/20 rounded-lg p-4">
            <div className="text-3xl mb-2">⏱️</div>
            <h4 className="font-bold text-white mb-2">Response Time</h4>
            <p className="text-gray-300 text-sm">
              90% faster anomaly detection and response compared to manual inspection
            </p>
          </div>
          <div className="bg-purple-900/20 rounded-lg p-4">
            <div className="text-3xl mb-2">🔧</div>
            <h4 className="font-bold text-white mb-2">Equipment Life</h4>
            <p className="text-gray-300 text-sm">
              25% increase in equipment lifespan through proactive maintenance
            </p>
          </div>
        </div>
      </div>

      {/* Disclaimer */}
      <div className="mt-8 bg-yellow-900/20 border border-yellow-500/50 rounded-lg p-4">
        <p className="text-yellow-200 text-center">
          ⚠️ <strong>Simulation Mode:</strong> All sensor readings and alerts are simulated data for demonstration.
          Real implementation would use IoT sensors and cloud infrastructure for actual monitoring.
        </p>
      </div>
    </div>
  );
}

export default InfraOS;
